{"file_path":"src/parser.js","content":"/**
 * TOML Parser
 * 
 * Parses TOML configuration documents and builds a tree structure.
 */

export class ParseError extends Error {
  constructor(lineNum, reason) {
    super(`error: line ${lineNum}: ${reason}`)
    this.lineNum = lineNum
    this.reason = reason
  }
}

export class Parser {
  constructor(input) {
    this.lines = input.split('\n')
    // Drop empty tail from trailing newline
    if (this.lines.length > 0 && this.lines[this.lines.length - 1] === '') {
      this.lines.pop()
    }
    this.lineNum = 0
    this.root = {}
    this.currentTable = this.root
    this.currentTablePath = []
    this.definedTables = new Set()
    this.definedKeys = new Set()
  }

  parse() {
    for (this.lineNum = 0; this.lineNum < this.lines.length; this.lineNum++) {
      const line = this.lines[this.lineNum]
      this.parseLine(line)
    }
    return this.root
  }

  parseLine(line) {
    // Remove comments and trailing whitespace
    const trimmedLine = this.removeComment(line)

    if (this.isEmptyLine(trimmedLine)) {
      return
    }

    const firstChar = this.firstNonWhitespace(trimmedLine)

    if (firstChar === '[') {
      this.parseHeader(trimmedLine)
    } else {
      this.parseKeyValue(trimmedLine)
    }
  }

  removeComment(line) {
    let inBasicString = false
    let inLiteralString = false
    let escaped = false

    for (let i = 0; i < line.length; i++) {
      const char = line[i]

      if (inBasicString) {
        if (escaped) {
          escaped = false
        } else if (char === '\\') {
          escaped = true
        } else if (char === '"') {
          inBasicString = false
        }
      } else if (inLiteralString) {
        if (char === "'") {
          inLiteralString = false
        }
      } else {
        if (char === '"') {
          inBasicString = true
        } else if (char === "'") {
          inLiteralString = true
        } else if (char === '#' || char === ';') {
          return line.substring(0, i)
        }
      }
    }

    return line
  }

  isEmptyLine(line) {
    for (let i = 0; i < line.length; i++) {
      const char = line[i]
      if (char !== ' ' && char !== '\t') {
        return false
      }
    }
    return true
  }

  firstNonWhitespace(line) {
    for (let i = 0; i < line.length; i++) {
      const char = line[i]
      if (char !== ' ' && char !== '\t') {
        return char
      }
    }
    return null
  }

  parseHeader(line) {
    const trimmed = line.trim()

    if (trimmed.startsWith('[[')) {
      // Array of tables
      const endIdx = trimmed.indexOf(']]')
      if (endIdx === -1) {
        throw new ParseError(this.lineNum + 1, 'unterminated table header')
      }

      const headerContent = trimmed.substring(2, endIdx)
      const afterClose = trimmed.substring(endIdx + 2)

      if (!this.isOnlyWhitespaceOrComment(afterClose)) {
        throw new ParseError(this.lineNum + 1, 'trailing text after a table header')
      }

      const nameStr = headerContent.trim()
      const path = this.parseDottedName(nameStr)

      this.createArrayOfTables(path)
    } else if (trimmed.startsWith('[')) {
      // Regular table
      const endIdx = trimmed.indexOf(']')
      if (endIdx === -1) {
        throw new ParseError(this.lineNum + 1, 'unterminated table header')
      }

      const headerContent = trimmed.substring(1, endIdx)
      const afterClose = trimmed.substring(endIdx + 1)

      if (!this.isOnlyWhitespaceOrComment(afterClose)) {
        throw new ParseError(this.lineNum + 1, 'trailing text after a table header')
      }

      const nameStr = headerContent.trim()
      const path = this.parseDottedName(nameStr)

      this.createTable(path)
    }
  }

  isOnlyWhitespaceOrComment(str) {
    for (let i = 0; i < str.length; i++) {
      const char = str[i]
      if (char === ' ' || char === '\t') {
        continue
      }
      if (char === '#' || char === ';') {
        return true
      }
      return false
    }
    return true
  }

  parseDottedName(str) {
    const parts = []
    let current = ''
    let i = 0

    while (i < str.length) {
      const char = str[i]

      if (char === ' ' || char === '\t') {
        if (current) {
          parts.push(current)
          current = ''
        }
        i++
      } else if (char === '.') {
        if (current) {
          parts.push(current)
          current = ''
        }
        i++
      } else if (char === '"') {
        // Quoted name
        i++
        const [name, nextIdx] = this.parseBasicString(str, i)
        parts.push(name)
        i = nextIdx
      } else if (char === "'") {
        // Single-quoted name
        i++
        const [name, nextIdx] = this.parseLiteralString(str, i)
        parts.push(name)
        i = nextIdx
      } else {
        // Bare word
        const start = i
        while (i < str.length && this.isNameChar(str[i])) {
          i++
        }
        if (i === start) {
          throw new ParseError(this.lineNum + 1, 'expected a name')
        }
        parts.push(str.substring(start, i))
      }
    }

    if (current) {
      parts.push(current)
    }

    if (parts.length === 0) {
      throw new ParseError(this.lineNum + 1, 'expected a name')
    }

    return parts
  }

  isNameChar(char) {
    const code = char.charCodeAt(0)
    return (code >= 65 && code <= 90) ||    // A-Z
           (code >= 97 && code <= 122) ||   // a-z
           (code >= 48 && code <= 57) ||    // 0-9
           char === '_' || char === '-'
  }

  createTable(path) {
    const pathStr = path.join('.')
    const tableKey = 'table:' + pathStr

    if (this.definedTables.has(tableKey)) {
      throw new ParseError(this.lineNum + 1, `table ${pathStr} is defined twice`)
    }

    this.definedTables.add(tableKey)

    let current = this.root
    for (let i = 0; i < path.length; i++) {
      const key = path[i]

      if (!(key in current)) {
        current[key] = {}
      } else if (typeof current[key] !== 'object' || Array.isArray(current[key])) {
        const parentPath = path.slice(0, i).join('.')
        const fullPath = parentPath ? parentPath + '.' + key : key
        throw new ParseError(this.lineNum + 1, `${fullPath} is not a table`)
      } else if (!Array.isArray(current[key])) {
        // Table exists and is a table - check if it was explicitly defined
        const subPath = path.slice(0, i + 1).join('.')
        const subTableKey = 'table:' + subPath
        if (this.definedTables.has(subTableKey)) {
          // It was explicitly defined, so we can't use it again
          throw new ParseError(this.lineNum + 1, `table ${pathStr} is defined twice`)
        }
      }

      current = current[key]
    }

    this.currentTable = current
    this.currentTablePath = path
  }

  createArrayOfTables(path) {
    const pathStr = path.join('.')

    let current = this.root
    for (let i = 0; i < path.length - 1; i++) {
      const key = path[i]

      if (!(key in current)) {
        current[key] = {}
      } else if (!this.isTable(current[key]) && !this.isArrayOfTables(current[key])) {
        throw new ParseError(this.lineNum + 1, `${path.slice(0, i + 1).join('.')} is not a table`)
      }

      current = current[key]
      if (Array.isArray(current)) {
        current = current[current.length - 1]
      }
    }

    const lastKey = path[path.length - 1]
    if (!(lastKey in current)) {
      current[lastKey] = []
    } else if (!Array.isArray(current[lastKey])) {
      throw new ParseError(this.lineNum + 1, `${pathStr} is not an array of tables`)
    }

    const newTable = {}
    current[lastKey].push(newTable)
    this.currentTable = newTable
    this.currentTablePath = path
  }

  isTable(obj) {
    return typeof obj === 'object' && obj !== null && !Array.isArray(obj)
  }

  isArrayOfTables(obj) {
    return Array.isArray(obj) && (obj.length === 0 || this.isTable(obj[0]))
  }

  parseKeyValue(line) {
    const eqIdx = this.findEquals(line)
    if (eqIdx === -1) {
      throw new ParseError(this.lineNum + 1, 'expected key = value')
    }

    const keyStr = line.substring(0, eqIdx).trim()
    const valueStr = line.substring(eqIdx + 1)

    if (!keyStr) {
      throw new ParseError(this.lineNum + 1, 'expected a name')
    }

    const path = this.parseDottedName(keyStr)
    const value = this.parseValue(valueStr)

    this.setKeyValue(path, value)
  }

  findEquals(line) {
    let inBasicString = false
    let inLiteralString = false
    let inArray = false
    let inInlineTable = false
    let escaped = false

    for (let i = 0; i < line.length; i++) {
      const char = line[i]

      if (inBasicString) {
        if (escaped) {
          escaped = false
        } else if (char === '\\') {
          escaped = true
        } else if (char === '"') {
          inBasicString = false
        }
      } else if (inLiteralString) {
        if (char === "'") {
          inLiteralString = false
        }
      } else if (inArray) {
        if (char === '"') {
          inBasicString = true
        } else if (char === "'") {
          inLiteralString = true
        } else if (char === ']') {
          inArray = false
        }
      } else if (inInlineTable) {
        if (char === '"') {
          inBasicString = true
        } else if (char === "'") {
          inLiteralString = true
        } else if (char === '}') {
          inInlineTable = false
        }
      } else {
        if (char === '"') {
          inBasicString = true
        } else if (char === "'") {
          inLiteralString = true
        } else if (char === '[') {
          inArray = true
        } else if (char === '{') {
          inInlineTable = true
        } else if (char === '=') {
          return i
        }
      }
    }

    return -1
  }

  setKeyValue(path, value) {
    let current = this.currentTable

    for (let i = 0; i < path.length - 1; i++) {
      const key = path[i]

      if (!(key in current)) {
        current[key] = {}
      } else if (typeof current[key] !== 'object' || Array.isArray(current[key])) {
        const fullPath = [...this.currentTablePath, ...path.slice(0, i + 1)].join('.')
        throw new ParseError(this.lineNum + 1, `${fullPath} is not a table`)
      }

      current = current[key]
    }

    const lastKey = path[path.length - 1]
    const fullPath = [...this.currentTablePath, ...path].join('.')

    if (lastKey in current) {
      throw new ParseError(this.lineNum + 1, `key ${fullPath} is defined twice`)
    }

    current[lastKey] = value
  }

  parseValue(str) {
    const trimmed = str.trim()

    if (!trimmed) {
      throw new ParseError(this.lineNum + 1, 'expected a value')
    }

    let valueStr = ''
    let i = 0

    // Find where the value ends (at comment or end of string)
    while (i < trimmed.length) {
      const char = trimmed[i]

      if (char === '"') {
        // Basic string
        valueStr = trimmed
        break
      } else if (char === "'") {
        // Literal string
        valueStr = trimmed
        break
      } else if (char === '[') {
        // Array
        valueStr = trimmed
        break
      } else if (char === '{') {
        // Inline table
        valueStr = trimmed
        break
      } else if (char === '#' || char === ';') {
        break
      } else if (char === ' ' || char === '\t' || char === ',' || char === ']' || char === '}') {
        valueStr = trimmed.substring(0, i)
        break
      } else {
        i++
      }
    }

    if (!valueStr) {
      valueStr = trimmed
    }

    // Parse the value
    const [value, endIdx] = this.parseValueToken(valueStr, 0)

    // Check for trailing text
    const afterValue = valueStr.substring(endIdx).trim()
    if (afterValue && afterValue[0] !== '#' && afterValue[0] !== ';') {
      throw new ParseError(this.lineNum + 1, 'trailing text after a value')
    }

    return value
  }

  parseValueToken(str, startIdx = 0) {
    let i = startIdx

    // Skip leading whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
      i++
    }

    if (i >= str.length) {
      throw new ParseError(this.lineNum + 1, 'expected a value')
    }

    const char = str[i]

    // Boolean
    if (str.substring(i, i + 4) === 'true') {
      return [true, i + 4]
    }
    if (str.substring(i, i + 5) === 'false') {
      return [false, i + 5]
    }

    // Strings
    if (char === '"') {
      return this.parseBasicStringValue(str, i + 1)
    }
    if (char === "'") {
      return this.parseLiteralStringValue(str, i + 1)
    }

    // Arrays
    if (char === '[') {
      return this.parseArray(str, i + 1)
    }

    // Inline tables
    if (char === '{') {
      return this.parseInlineTable(str, i + 1)
    }

    // Number or invalid
    let numStr = ''
    let j = i
    let hasDecimal = false
    let hasExp = false

    // Handle sign
    if (str[j] === '+' || str[j] === '-') {
      numStr += str[j]
      j++
    }

    // Read digits and separators
    while (j < str.length) {
      const c = str[j]

      if (c >= '0' && c <= '9') {
        numStr += c
        j++
      } else if (c === '_') {
        if (j === i || j === str.length - 1) {
          break
        }
        if (str[j - 1] === '_' || str[j + 1] < '0' || str[j + 1] > '9') {
          break
        }
        numStr += c
        j++
      } else if (c === '.' && !hasDecimal && !hasExp) {
        hasDecimal = true
        numStr += c
        j++
      } else if ((c === 'e' || c === 'E') && !hasExp) {
        hasExp = true
        numStr += c
        j++
        // Handle sign after e
        if (j < str.length && (str[j] === '+' || str[j] === '-')) {
          numStr += str[j]
          j++
        }
      } else {
        break
      }
    }

    if (!numStr || numStr === '+' || numStr === '-') {
      throw new ParseError(this.lineNum + 1, `invalid value ${str.substring(i, i + 10)}`)
    }

    // Clean up underscores
    const cleanNum = numStr.replace(/_/g, '')

    try {
      if (hasDecimal || hasExp) {
        const floatVal = parseFloat(cleanNum)
        if (isNaN(floatVal)) {
          throw new ParseError(this.lineNum + 1, `invalid value ${numStr}`)
        }
        return [floatVal, j]
      } else {
        const intVal = parseInt(cleanNum, 10)
        if (isNaN(intVal)) {
          throw new ParseError(this.lineNum + 1, `invalid value ${numStr}`)
        }
        return [intVal, j]
      }
    } catch (e) {
      throw new ParseError(this.lineNum + 1, `invalid value ${numStr}`)
    }
  }

  parseBasicStringValue(str, startIdx) {
    let result = ''
    let i = startIdx
    let escaped = false

    while (i < str.length) {
      const char = str[i]

      if (escaped) {
        switch (char) {
          case '"':
            result += '"'
            break
          case '\\':
            result += '\\'
            break
          case 'n':
            result += '\n'
            break
          case 't':
            result += '\t'
            break
          case 'r':
            result += '\r'
            break
          case '0':
            result += '\0'
            break
          case 'u':
            if (i + 4 >= str.length) {
              throw new ParseError(this.lineNum + 1, 'unterminated string')
            }
            const hex = str.substring(i + 1, i + 5)
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
              throw new ParseError(this.lineNum + 1, `invalid escape \\u${hex}`)
            }
            result += String.fromCharCode(parseInt(hex, 16))
            i += 4
            break
          default:
            throw new ParseError(this.lineNum + 1, `invalid escape \\${char}`)
        }
        escaped = false
        i++
      } else if (char === '\\') {
        escaped = true
        i++
      } else if (char === '"') {
        return [result, i + 1]
      } else {
        result += char
        i++
      }
    }

    throw new ParseError(this.lineNum + 1, 'unterminated string')
  }

  parseLiteralStringValue(str, startIdx) {
    let result = ''
    let i = startIdx

    while (i < str.length) {
      const char = str[i]
      if (char === "'") {
        return [result, i + 1]
      }
      result += char
      i++
    }

    throw new ParseError(this.lineNum + 1, 'unterminated string')
  }

  parseBasicString(str, startIdx) {
    let result = ''
    let i = startIdx
    let escaped = false

    while (i < str.length) {
      const char = str[i]

      if (escaped) {
        switch (char) {
          case '"':
            result += '"'
            break
          case '\\':
            result += '\\'
            break
          case 'n':
            result += '\n'
            break
          case 't':
            result += '\t'
            break
          case 'r':
            result += '\r'
            break
          case '0':
            result += '\0'
            break
          case 'u':
            if (i + 4 >= str.length) {
              throw new ParseError(this.lineNum + 1, 'unterminated string')
            }
            const hex = str.substring(i + 1, i + 5)
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
              throw new ParseError(this.lineNum + 1, `invalid escape \\u${hex}`)
            }
            result += String.fromCharCode(parseInt(hex, 16))
            i += 4
            break
          default:
            throw new ParseError(this.lineNum + 1, `invalid escape \\${char}`)
        }
        escaped = false
        i++
      } else if (char === '\\') {
        escaped = true
        i++
      } else if (char === '"') {
        return [result, i + 1]
      } else {
        result += char
        i++
      }
    }

    throw new ParseError(this.lineNum + 1, 'unterminated string')
  }

  parseLiteralString(str, startIdx) {
    let result = ''
    let i = startIdx

    while (i < str.length) {
      const char = str[i]
      if (char === "'") {
        return [result, i + 1]
      }
      result += char
      i++
    }

    throw new ParseError(this.lineNum + 1, 'unterminated string')
  }

  parseArray(str, startIdx) {
    let i = startIdx
    const values = []
    let first = true

    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) {
      i++
    }

    while (i < str.length) {
      const char = str[i]

      if (char === ']') {
        return [values, i + 1]
      }

      if (!first) {
        if (char !== ',') {
          throw new ParseError(this.lineNum + 1, 'unterminated array')
        }
        i++

        // Skip whitespace after comma
        while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) {
          i++
        }

        // Allow trailing comma
        if (i < str.length && str[i] === ']') {
          return [values, i + 1]
        }
      }

      if (i >= str.length) {
        throw new ParseError(this.lineNum + 1, 'unterminated array')
      }

      const [value, nextIdx] = this.parseValueToken(str, i)
      values.push(value)
      i = nextIdx

      // Skip whitespace
      while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) {
        i++
      }

      first = false
    }

    throw new ParseError(this.lineNum + 1, 'unterminated array')
  }

  parseInlineTable(str, startIdx) {
    let i = startIdx
    const table = {}
    let first = true

    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
      i++
    }

    while (i < str.length) {
      const char = str[i]

      if (char === '}') {
        return [table, i + 1]
      }

      if (!first) {
        if (char !== ',') {
          throw new ParseError(this.lineNum + 1, 'unterminated inline table')
        }
        i++

        // Skip whitespace after comma
        while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
          i++
        }
      }

      if (i >= str.length || str[i] === '}') {
        throw new ParseError(this.lineNum + 1, 'unterminated inline table')
      }

      // Parse key
      let keyStart = i
      let keyStr = ''

      if (str[i] === '"') {
        i++
        const [key, nextIdx] = this.parseBasicString(str, i)
        keyStr = key
        i = nextIdx
      } else if (str[i] === "'") {
        i++
        const [key, nextIdx] = this.parseLiteralString(str, i)
        keyStr = key
        i = nextIdx
      } else {
        // Bare word
        while (i < str.length && this.isNameChar(str[i])) {
          i++
        }
        if (i === keyStart) {
          throw new ParseError(this.lineNum + 1, 'expected a name')
        }
        keyStr = str.substring(keyStart, i)
      }

      // Skip whitespace
      while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
        i++
      }

      // Expect =
      if (i >= str.length || str[i] !== '=') {
        throw new ParseError(this.lineNum + 1, 'expected = in an inline table')
      }
      i++

      // Skip whitespace
      while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
        i++
      }

      // Parse value
      const [value, nextIdx] = this.parseValueToken(str, i)
      table[keyStr] = value
      i = nextIdx

      // Skip whitespace
      while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
        i++
      }

      first = false
    }

    throw new ParseError(this.lineNum + 1, 'unterminated inline table')
  }
}
