{"file_path":"src/parser.js","content":"/**
 * TOML Parser
 * 
 * Parses TOML configuration documents and builds a tree structure.
 */

export class ParseError extends Error {
  constructor(lineNum, reason) {
    super(`error: line ${lineNum}: ${reason}`)
    this.lineNum = lineNum
    this.reason = reason
  }
}

export class Parser {
  constructor(input) {
    this.lines = input.split('\n')
    // Drop empty tail from trailing newline
    if (this.lines.length > 0 && this.lines[this.lines.length - 1] === '') {
      this.lines.pop()
    }
    this.lineNum = 0
    this.root = {}
    this.currentTable = this.root
    this.currentTablePath = []
    this.definedTables = new Set()
    this.definedKeys = new Set()
  }

  parse() {
    for (this.lineNum = 0; this.lineNum < this.lines.length; this.lineNum++) {
      const line = this.lines[this.lineNum]
      this.parseLine(line)
    }
    return this.root
  }

  parseLine(line) {
    // Remove comments and trailing whitespace
    const trimmedLine = this.removeComment(line)

    if (this.isEmptyLine(trimmedLine)) {
      return
    }

    const firstChar = this.firstNonWhitespace(trimmedLine)

    if (firstChar === '[') {
      this.parseHeader(trimmedLine)
    } else {
      this.parseKeyValue(trimmedLine)
    }
  }

  removeComment(line) {
    let inBasicString = false
    let inLiteralString = false
    let escaped = false

    for (let i = 0; i < line.length; i++) {
      const char = line[i]

      if (inBasicString) {
        if (escaped) {
          escaped = false
        } else if (char === '\\') {
          escaped = true
        } else if (char === '"') {
          inBasicString = false
        }
      } else if (inLiteralString) {
        if (char === "'") {
          inLiteralString = false
        }
      } else {
        if (char === '"') {
          inBasicString = true
        } else if (char === "'") {
          inLiteralString = true
        } else if (char === '#' || char === ';') {
          return line.substring(0, i)
        }
      }
    }

    return line
  }

  isEmptyLine(line) {
    for (let i = 0; i < line.length; i++) {
      const char = line[i]
      if (char !== ' ' && char !== '\t') {
        return false
      }
    }
    return true
  }

  firstNonWhitespace(line) {
    for (let i = 0; i < line.length; i++) {
      const char = line[i]
      if (char !== ' ' && char !== '\t') {
        return char
      }
    }
    return null
  }

  parseHeader(line) {
    const trimmed = line.trim()

    if (trimmed.startsWith('[[')) {
      // Array of tables
      const endIdx = trimmed.indexOf(']]')
      if (endIdx === -1) {
        throw new ParseError(this.lineNum + 1, 'unterminated table header')
      }

      const headerContent = trimmed.substring(2, endIdx)
      const afterClose = trimmed.substring(endIdx + 2)

      if (!this.isOnlyWhitespaceOrComment(afterClose)) {
        throw new ParseError(this.lineNum + 1, 'trailing text after a table header')
      }

      const nameStr = headerContent.trim()
      const path = this.parseDottedName(nameStr)

      this.createArrayOfTables(path)
    } else if (trimmed.startsWith('[')) {
      // Regular table
      const endIdx = trimmed.indexOf(']')
      if (endIdx === -1) {
        throw new ParseError(this.lineNum + 1, 'unterminated table header')
      }

      const headerContent = trimmed.substring(1, endIdx)
      const afterClose = trimmed.substring(endIdx + 1)

      if (!this.isOnlyWhitespaceOrComment(afterClose)) {
        throw new ParseError(this.lineNum + 1, 'trailing text after a table header')
      }

      const nameStr = headerContent.trim()
      const path = this.parseDottedName(nameStr)

      this.createTable(path)
    }
  }

  isOnlyWhitespaceOrComment(str) {
    for (let i = 0; i < str.length; i++) {
      const char = str[i]
