    const parts = []
    let current = ''
    let i = 0

    while (i < str.length) {
      const char = str[i]

      if (char === ' ' || char === '\t') {
        if (current) {
          parts.push(current)
          current = ''
        }
        i++
      } else if (char === '.') {
        if (current) {
          parts.push(current)
          current = ''
