      while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) {
        i++
      }

      first = false
    }

    throw new ParseError(this.lineNum + 1, 'unterminated array')
  }

  parseInlineTable(str, startIdx) {
    let i = startIdx
    const table = {}
    let first = true

    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
