      const char = line[i]

      if (inBasicString) {
        if (escaped) {
          escaped = false
        } else if (char === '\\') {
          escaped = true
        } else if (char === '"') {
          inBasicString = false
        }
      } else if (inLiteralString) {
        if (char === "'") {
          inLiteralString = false
        }
      } else if (inArray) {
        if (char === '"') {
          inBasicString = true
        } else if (char === "'") {
          inLiteralString = true
        } else if (char === ']') {
          inArray = false
        }
      } else if (inInlineTable) {
        if (char === '"') {
          inBasicString = true
        } else if (char === "'") {
          inLiteralString = true
        } else if (char === '}') {
          inInlineTable = false
        }
      } else {
        if (char === '"') {
          inBasicString = true
        } else if (char === "'") {
          inLiteralString = true
        } else if (char === '[') {
          inArray = true
        } else if (char === '{') {
          inInlineTable = true
        } else if (char === '=') {
          return i
        }
      }
    }

    return -1
  }

  setKeyValue(path, value) {
    let current = this.currentTable

    for (let i = 0; i < path.length - 1; i++) {
      const key = path[i]

      if (!(key in current)) {
        current[key] = {}
      } else if (typeof current[key] !== 'object' || Array.isArray(current[key])) {
        const fullPath = [...this.currentTablePath, ...path.slice(0, i + 1)].join('.')
        throw new ParseError(this.lineNum + 1, `${fullPath} is not a table`)
      }

      current = current[key]
    }

    const lastKey = path[path.length - 1]
    const fullPath = [...this.currentTablePath, ...path].join('.')

