    const trimmed = str.trim()

    if (!trimmed) {
      throw new ParseError(this.lineNum + 1, 'expected a value')
    }

    let valueStr = ''
    let i = 0

    // Find where the value ends (at comment or end of string)
    while (i < trimmed.length) {
      const char = trimmed[i]

      if (char === '"') {
        // Basic string
        valueStr = trimmed
        break
      } else if (char === "'") {
        // Literal string
        valueStr = trimmed
        break
      } else if (char === '[') {
        // Array
        valueStr = trimmed
        break
      } else if (char === '{') {
        // Inline table
        valueStr = trimmed
        break
      } else if (char === '#' || char === ';') {
        break
      } else if (char === ' ' || char === '\t' || char === ',' || char === ']' || char === '}') {
        valueStr = trimmed.substring(0, i)
        break
      } else {
        i++
