    let i = startIdx

    // Skip leading whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
      i++
    }

    if (i >= str.length) {
      throw new ParseError(this.lineNum + 1, 'expected a value')
    }

    const char = str[i]

    // Boolean
    if (str.substring(i, i + 4) === 'true') {
      return [true, i + 4]
    }
    if (str.substring(i, i + 5) === 'false') {
      return [false, i + 5]
    }

    // Strings
    if (char === '"') {
      return this.parseBasicStringValue(str, i + 1)
    }
    if (char === "'") {
      return this.parseLiteralStringValue(str, i + 1)
    }

    // Arrays
    if (char === '[') {
      return this.parseArray(str, i + 1)
    }

    // Inline tables
    if (char === '{') {
      return this.parseInlineTable(str, i + 1)
    }

    // Number or invalid
    let numStr = ''
    let j = i
    let hasDecimal = false
    let hasExp = false

    // Handle sign
    if (str[j] === '+' || str[j] === '-') {
      numStr += str[j]
      j++
    }

    // Read digits and separators
    while (j < str.length) {
      const c = str[j]

      if (c >= '0' && c <= '9') {
        numStr += c
        j++
      } else if (c === '_') {
        if (j === i || j === str.length - 1) {
          break
        }
        if (str[j - 1] === '_' || str[j + 1] < '0' || str[j + 1] > '9') {
          break
        }
        numStr += c
        j++
      } else if (c === '.' && !hasDecimal && !hasExp) {
        hasDecimal = true
        numStr += c
        j++
      } else if ((c === 'e' || c === 'E') && !hasExp) {
        hasExp = true
        numStr += c
        j++
        // Handle sign after e
        if (j < str.length && (str[j] === '+' || str[j] === '-')) {
          numStr += str[j]
          j++
        }
      } else {
        break
      }
    }

    if (!numStr || numStr === '+' || numStr === '-') {
      throw new ParseError(this.lineNum + 1, `invalid value ${str.substring(i, i + 10)}`)
    }

