    let result = ''
    let i = startIdx

    while (i < str.length) {
      const char = str[i]
      if (char === "'") {
        return [result, i + 1]
      }
      result += char
      i++
    }

    throw new ParseError(this.lineNum + 1, 'unterminated string')
  }

