    let result = ''
    let i = startIdx
    let escaped = false

    while (i < str.length) {
      const char = str[i]

      if (escaped) {
        switch (char) {
          case '"':
            result += '"'
            break
          case '\\':
            result += '\\'
            break
          case 'n':
            result += '\n'
            break
          case 't':
            result += '\t'
            break
          case 'r':
            result += '\r'
            break
          case '0':
            result += '\0'
            break
          case 'u':
            if (i + 4 >= str.length) {
              throw new ParseError(this.lineNum + 1, 'unterminated string')
            }
            const hex = str.substring(i + 1, i + 5)
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
              throw new ParseError(this.lineNum + 1, `invalid escape \\u${hex}`)
            }
            result += String.fromCharCode(parseInt(hex, 16))
            i += 4
            break
          default:
            throw new ParseError(this.lineNum + 1, `invalid escape \\${char}`)
        }
        escaped = false
        i++
      } else if (char === '\\') {
        escaped = true
        i++
      } else if (char === '"') {
        return [result, i + 1]
      } else {
        result += char
        i++
      }
    }

    throw new ParseError(this.lineNum + 1, 'unterminated string')
  }

  parseLiteralString(str, startIdx) {
    let result = ''
    let i = startIdx

    while (i < str.length) {
      const char = str[i]
      if (char === "'") {
        return [result, i + 1]
      }
      result += char
      i++
    }

    throw new ParseError(this.lineNum + 1, 'unterminated string')
  }

  parseArray(str, startIdx) {
    let i = startIdx
    const values = []
    let first = true

    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) {
      i++
    }

    while (i < str.length) {
      const char = str[i]

      if (char === ']') {
        return [values, i + 1]
      }

      if (!first) {
        if (char !== ',') {
          throw new ParseError(this.lineNum + 1, 'unterminated array')
        }
        i++

        // Skip whitespace after comma
        while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) {
          i++
        }

        // Allow trailing comma
        if (i < str.length && str[i] === ']') {
          return [values, i + 1]
        }
      }

      if (i >= str.length) {
        throw new ParseError(this.lineNum + 1, 'unterminated array')
      }

      const [value, nextIdx] = this.parseValueToken(str, i)
      values.push(value)
      i = nextIdx

      // Skip whitespace
      while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) {
        i++
      }

      first = false
    }

    throw new ParseError(this.lineNum + 1, 'unterminated array')
  }

  parseInlineTable(str, startIdx) {
    let i = startIdx
    const table = {}
    let first = true

    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
      i++
    }

    while (i < str.length) {
      const char = str[i]

      if (char === '}') {
        return [table, i + 1]
      }

      if (!first) {
        if (char !== ',') {
          throw new ParseError(this.lineNum + 1, 'unterminated inline table')
        }
        i++

        // Skip whitespace after comma
        while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
          i++
        }
      }

      if (i >= str.length || str[i] === '}') {
        throw new ParseError(this.lineNum + 1, 'unterminated inline table')
      }

      // Parse key
      let keyStart = i
      let keyStr = ''

      if (str[i] === '"') {
        i++
        const [key, nextIdx] = this.parseBasicString(str, i)
        keyStr = key
        i = nextIdx
      } else if (str[i] === "'") {
        i++
        const [key, nextIdx] = this.parseLiteralString(str, i)
        keyStr = key
        i = nextIdx
      } else {
        // Bare word
        while (i < str.length && this.isNameChar(str[i])) {
          i++
        }
        if (i === keyStart) {
          throw new ParseError(this.lineNum + 1, 'expected a name')
        }
        keyStr = str.substring(keyStart, i)
      }

      // Skip whitespace
      while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
        i++
      }

      // Expect =
      if (i >= str.length || str[i] !== '=') {
        throw new ParseError(this.lineNum + 1, 'expected = in an inline table')
      }
      i++

      // Skip whitespace
      while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
        i++
      }

      // Parse value
      const [value, nextIdx] = this.parseValueToken(str, i)
      table[keyStr] = value
      i = nextIdx

      // Skip whitespace
      while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
        i++
      }

      first = false
    }

    throw new ParseError(this.lineNum + 1, 'unterminated inline table')
  }
}
