function formatJSON(obj, indent) {
  const spaces = '  '.repeat(indent)
  const nextSpaces = '  '.repeat(indent + 1)

  if (obj === null) {
    return 'null'
  }

  if (typeof obj === 'boolean') {
    return obj ? 'true' : 'false'
  }

  if (typeof obj === 'number') {
    return String(obj)
  }

  if (typeof obj === 'string') {
    return JSON.stringify(obj)
  }

  if (Array.isArray(obj)) {
    if (obj.length === 0) {
      return '[]'
    }

    // Check if this is an array of tables
    if (obj.length > 0 && isPlainObject(obj[0])) {
      let result = '[\n'
      for (let i = 0; i < obj.length; i++) {
        result += nextSpaces + formatJSON(obj[i], indent + 1)
        if (i < obj.length - 1) {
          result += ','
        }
        result += '\n'
      }
      result += spaces + ']'
      return result
    }

    // Regular array
    let result = '[\n'
    for (let i = 0; i < obj.length; i++) {
      result += nextSpaces + formatJSON(obj[i], indent + 1)
      if (i < obj.length - 1) {
        result += ','
      }
      result += '\n'
    }
    result += spaces + ']'
    return result
  }

  if (isPlainObject(obj)) {
    const keys = Object.keys(obj).sort()

    if (keys.length === 0) {
      return '{}'
    }

    let result = '{\n'
    for (let i = 0; i < keys.length; i++) {
      const key = keys[i]
      result += nextSpaces + JSON.stringify(key) + ': ' + formatJSON(obj[key], indent + 1)
      if (i < keys.length - 1) {
        result += ','
      }
      result += '\n'
    }
    result += spaces + '}'
    return result
  }

  return JSON.stringify(obj)
}

function isPlainObject(obj) {
  return obj !== null && typeof obj === 'object' && !Array.isArray(obj)
}

function walkKeys(obj, path, lines) {
  if (Array.isArray(obj)) {
    // Array of tables
    for (let i = 0; i < obj.length; i++) {
      const itemPath = path + '[' + i + ']'
      lines.push(itemPath + ' array')
      walkKeys(obj[i], itemPath, lines)
    }
  } else if (isPlainObject(obj)) {
    // Object/table
    if (path) {
      lines.push(path + ' table')
    }

    const keys = Object.keys(obj).sort()
    for (const key of keys) {
      const value = obj[key]
      const childPath = path ? path + '.' + key : key

      if (Array.isArray(value)) {
        walkKeys(value, childPath, lines)
      } else if (isPlainObject(value)) {
        walkKeys(value, childPath, lines)
      } else if (typeof value === 'boolean') {
        lines.push(childPath + ' boolean')
      } else if (typeof value === 'number') {
        if (Number.isInteger(value)) {
          lines.push(childPath + ' integer')
        } else {
          lines.push(childPath + ' float')
        }
      } else if (typeof value === 'string') {
        lines.push(childPath + ' string')
      }
    }
  }
}
