{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { Parser, ParseError } from './parser.js'
import { outputJSON, outputKeys } from './output.js'

const args = process.argv.slice(2)

if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const mode = args[0]

// Read stdin
let input = ''

process.stdin.setEncoding('utf8')

process.stdin.on('data', chunk => {
  input += chunk
})

process.stdin.on('end', () => {
  try {
    const parser = new Parser(input)
    const root = parser.parse()

    if (mode === 'json') {
      process.stdout.write(outputJSON(root))
    } else if (mode === 'keys') {
      process.stdout.write(outputKeys(root))
    }

    process.exit(0)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(err.message + '\n')
    } else {
      process.stderr.write('error: ' + err.message + '\n')
    }
    process.exit(2)
  }
})
"}

